#pragma once
class BulkParameterPanel final:public juce::Component{
public:
 struct Spec{juce::String field,label;double min,max,defaultValue;int decimals=0;juce::StringArray choices;};
 struct Row{Spec spec;juce::Label label;TimingField value;juce::ComboBox choice;};
 juce::Label title;juce::Viewport viewport;juce::Component content;std::vector<std::unique_ptr<Row>> rows;std::function<void(juce::String,double)> changed;
 BulkParameterPanel(){addAndMakeVisible(title);title.setText("Multiple files selected",juce::dontSendNotification);title.setJustificationType(juce::Justification::centred);title.setFont(juce::FontOptions(17,juce::Font::bold));addAndMakeVisible(viewport);viewport.setViewedComponent(&content,false);}
 void configure(int count,std::vector<Spec> specs,const std::vector<juce::var>& values){rows.clear();title.setText(juce::String(count)+" files selected",juce::dontSendNotification);for(auto spec:specs){auto row=std::make_unique<Row>();auto* item=row.get();item->spec=spec;content.addAndMakeVisible(item->label);item->label.setText(spec.label,juce::dontSendNotification);double first=values.empty()?spec.defaultValue:(double)values[0].getProperty(spec.field,spec.defaultValue);bool mixed=values.empty();for(auto& value:values)if(!value.hasProperty(spec.field)||std::abs((double)value.getProperty(spec.field,spec.defaultValue)-first)>1e-8)mixed=true;
 if(!spec.choices.isEmpty()){content.addAndMakeVisible(item->choice);item->choice.addItemList(spec.choices,1);item->choice.setTextWhenNothingSelected(mixed?"Mixed":"Choose");if(!mixed)item->choice.setSelectedId(juce::jlimit(1,spec.choices.size(),(int)first+1),juce::dontSendNotification);item->choice.onChange=[this,item]{if(changed)changed(item->spec.field,item->choice.getSelectedId()-1);};}
 else{content.addAndMakeVisible(item->value);item->value.minimum=spec.min;item->value.formatter=[spec](double v){return juce::String(v,spec.decimals);};item->value.setText(mixed?"Mixed":juce::String(first,spec.decimals),false);item->value.setTextToShowWhenEmpty("Mixed",juce::Colours::grey);item->value.onReturnKey=[this,item]{auto text=item->value.getText();if(!NumericInputFilter::valid(text,true))return;double value=juce::jlimit(item->spec.min,item->spec.max,text.getDoubleValue());if(item->spec.decimals==0)value=std::round(value);item->value.setText(juce::String(value,item->spec.decimals),false);if(changed)changed(item->spec.field,value);};}rows.push_back(std::move(row));}resized();}
 void resized()override{title.setBounds(0,0,getWidth(),72);viewport.setBounds(0,74,getWidth(),juce::jmax(0,getHeight()-74));int columns=getWidth()>=650?3:2,width=juce::jmax(120,(getWidth()-20)/columns);for(size_t i=0;i<rows.size();++i){int x=(i%columns)*width,y=(i/columns)*66;auto& r=*rows[i];r.label.setBounds(x+5,y,width-12,20);r.value.setBounds(x+5,y+21,width-15,27);r.choice.setBounds(r.value.getBounds());}content.setSize(getWidth()-16,((rows.size()+columns-1)/columns)*66+6);}
};
class FxAnchorBoxes final:public juce::Component{
 Processor& p;juce::TextButton add{"+"};juce::Viewport viewport;juce::Component content;std::vector<std::unique_ptr<TimingField>> fields;juce::String signature;
public:explicit FxAnchorBoxes(Processor& engine):p(engine){addAndMakeVisible(viewport);viewport.setViewedComponent(&content,false);viewport.setScrollBarsShown(false,true);addAndMakeVisible(add);add.onClick=[this]{auto bars=p.fxBars();bars.push_back(bars.back()+1);p.setFxBars(bars);sync();};}
 void sync(){auto bars=p.fxBars();juce::String next;for(int b:bars)next+=juce::String(b)+":";if(next==signature)return;for(auto& f:fields)if(f->hasKeyboardFocus(true)||f->isDragging())return;signature=next;fields.clear();for(size_t i=0;i<bars.size();++i){auto f=std::make_unique<TimingField>();auto* ptr=f.get();f->setText(juce::String(bars[i]),false);f->minimum=1;f->begin=[this]{p.beginEdit();};f->end=[this]{p.endEdit();};f->readValue=[this,i]{auto b=p.fxBars();return i<b.size()?b[i]:1;};f->writeValue=[this,i](double v){auto b=p.fxBars();if(i<b.size()){b[i]=juce::jlimit(1,100000,(int)std::round(v));p.setFxBars(b);}};f->onReturnKey=[ptr]{ptr->writeValue(ptr->getText().getDoubleValue());};f->setTooltip("Project bar. Right-click to remove this anchor.");f->popupAction=[this,i]{auto bars=p.fxBars();if(bars.size()<2)return;juce::PopupMenu menu;menu.addItem(1,"Remove anchor");auto safe=juce::Component::SafePointer<FxAnchorBoxes>(this);menu.showMenuAsync({},[safe,i](int choice){if(safe&&choice==1){auto bars=safe->p.fxBars();if(i<bars.size()&&bars.size()>1){bars.erase(bars.begin()+i);safe->giveAwayKeyboardFocus();safe->p.setFxBars(bars);safe->sync();}}});};content.addAndMakeVisible(*f);fields.push_back(std::move(f));}resized();}
 void resized()override{viewport.setBounds(0,0,juce::jmax(0,getWidth()-29),getHeight());add.setBounds(getWidth()-25,0,25,25);int x=0;for(auto& f:fields){int width=juce::jmax(32,14+f->getText().length()*9);f->setBounds(x,0,width,25);x+=width+4;}content.setSize(x,25);}
};
